with tarfile.open(r / 'source.tar') as archive:
    for name, expected in setup['baseline_hashes'].items():
        p = s / name
        if sha(p) != expected:
            p.write_bytes(archive.extractfile(name).read())
for name in ['mapper_key_probe.rs', 'late_bound_probe.rs']:
    (s / 'crates/tsr-checker/src' / name).unlink()
assert all(sha(s / p) == value for p, value in setup['baseline_hashes'].items())
(r / 'observer-restoration.json').write_text(json.dumps({
    'baseline_files': len(setup['baseline_hashes']),
    'all_baseline_source_hashes_match': True,
    'added_observer_modules_removed': True,
}, indent=2) + '\n')
p = s / 'crates/tsr-checker/src/members.rs'
original = p.read_text()
needle = '''        for (key, member) in self.late_bound_members_of(owner, false) {
            if key == name
                && let Some(symbol) = self.binder.symbol_of(member)
            {
                return Some(symbol);
            }
        }
'''
replacement = '''        let cache_key = (owner, false);
        if !self.late_bound_member_names.contains_key(&cache_key) {
            // Force exactly the existing miss path, including its re-entry marker.
            // The published vector retains the same ordered declarations as the result.
            let _ = self.late_bound_members_of(owner, false);
        }
        if let Some(symbol) = self.late_bound_member_names.get(&cache_key).and_then(|members| {
            members.iter().find_map(|(key, member)| {
                if key == name { self.binder.symbol_of(*member) } else { None }
            })
        }) {
            return Some(symbol);
        }
'''
assert original.count(needle) == 1
candidate = original.replace(needle, replacement)
tests = '''    #[test]
    fn late_bound_lookup_skips_unbound_duplicate_declarations() {
        with_checker("const key = 'late'; class Shape { [key] = 1 }", |checker, root| {
            let owner = checker.binder.lookup_local(root, "Shape").unwrap();
            let members = checker.late_bound_members_of(owner, false);
            assert_eq!(members.len(), 1);
            let member = members[0].1;
            let expected = checker.binder.symbol_of(member).unwrap();
            assert!(checker.binder.symbol_of(root).is_none());
            checker.late_bound_member_names.insert(
                (owner, false), vec![("late".into(), root), ("late".into(), member)]);
            for _ in 0..2 {
                assert_eq!(checker.get_property_of_declared_symbol(owner, "late", &mut Vec::new()), Some(expected));
                assert_eq!(checker.get_property_of_declared_symbol(owner, "absent", &mut Vec::new()), None);
            }
        });
    }

    #[test]
    fn late_bound_lookup_preserves_marker_then_recovers_inherited_identity() {
        with_checker("const key = 'late'; class Base { [key] = 1 } class Derived extends Base {}", |checker, root| {
            let base = checker.binder.lookup_local(root, "Base").unwrap();
            let derived = checker.binder.lookup_local(root, "Derived").unwrap();
            let expected = checker.get_property_of_declared_symbol(derived, "late", &mut Vec::new()).unwrap();
